package com.assetsphere.modules.storage;
import java.util.UUID; import jakarta.persistence.*; import lombok.Getter; import com.assetsphere.modules.common.BaseEntity;
@Getter @Entity @Table(name="storage_objects") public class StorageObject extends BaseEntity { @Column(name="workspace_id",nullable=false) private UUID workspaceId; @Column(name="checksum_sha256",nullable=false,length=64) private String checksumSha256; @Column(name="object_key",nullable=false,length=1024) private String objectKey; @Enumerated(EnumType.STRING) @Column(name="storage_provider",nullable=false,length=32) private StorageProvider storageProvider; @Column(name="file_size",nullable=false) private long fileSize; @Column(name="mime_type",nullable=false,length=255) private String mimeType; @Column(name="reference_count",nullable=false) private int referenceCount; protected StorageObject(){} public static StorageObject create(UUID workspaceId,String checksum,String key,long size,String type){StorageObject object=new StorageObject();object.workspaceId=workspaceId;object.checksumSha256=checksum;object.objectKey=key;object.storageProvider=StorageProvider.MINIO;object.fileSize=size;object.mimeType=type;object.referenceCount=1;return object;} public void incrementReferenceCount(){referenceCount++;} }
